            return new Pair(UP, LEFT);
        if (dir == UPRIGHT)
            return new Pair(UP, RIGHT);
        if (dir == DOWNLEFT)
            return new Pair(DOWN, LEFT);
        if (dir == DOWNRIGHT)
            return new Pair(DOWN, RIGHT);
        return null;
